export function mintWindow({openedAt,soldOutAt=null,now}){if(openedAt===null)return {phase:'unscheduled',closesAt:null};if(!Number.isSafeInteger(openedAt)||openedAt<0||!Number.isSafeInteger(now)||now<0||soldOutAt!==null&&(!Number.isSafeInteger(soldOutAt)||soldOutAt<openedAt))throw Error('Invalid mint timestamp');const closesAt=Math.min(openedAt+604800,soldOutAt??Infinity);return {phase:now<openedAt?'scheduled':now>=closesAt?'closed':'open',closesAt};}
